def compute_convstat(a, b, events, items):
    # Convergence entry tied to multidrill: the failure periods come from
    # the same event processing (nodes start up, links start at FILE's up
    # flag, t non-decreasing with equal-tick order kept, the first real
    # down opens a period that closes when its current down set empties,
    # a real down after a close reopens). Period U is the next period's
    # start, or b+1 for the last one.
    #
    # A flow is affected by a period when, during [start, U), one of its
    # records is unreachable (empty path) or its path differs from that
    # flow's most recent earlier record; the first non-empty record is the
    # baseline and never counts by itself. c is that flow's count of
    # adjacent path changes within [start, r] (or [start, U) with no r).
    # r is the earliest tick of [end, U) at which every affected flow's
    # latest path is non-empty (r = end if already so then); without
    # affected flows, while the period is open, or when the flows do not
    # recover in time, r and d are null.
    node_up = {}
    link_up = {}
    periods = []
    current = None  # [start, end, down_nodes, down_links] while open

    for t, kind, *rest in events:
        if kind == 0:
            node, up = rest
            current_before = node_up.get(node, True)
            if current_before == up:
                continue
            node_up[node] = up
            if up:
                if current is not None:
                    current[2].discard(node)
            else:
                if current is None:
                    current = [t, None, set(), set()]
                    periods.append(current)
                current[2].add(node)
        else:
            u, v, up = rest
            pair = (u, v)
            current_before = link_up.get(pair, True)
            if current_before == up:
                continue
            link_up[pair] = up
            if up:
                if current is not None:
                    current[3].discard(pair)
            else:
                if current is None:
                    current = [t, None, set(), set()]
                    periods.append(current)
                current[3].add(pair)
        if current is not None and not current[2] and not current[3]:
            current[1] = t
            current = None

    # Records grouped per flow in input order (globally non-decreasing t,
    # at most one per flow per tick), as (t, path) pairs.
    records_of = {}
    for t, f, path in items:
        records_of.setdefault(f, []).append((t, path))

    # Events at ticks beyond the records define periods with no records to
    # match, so ranges start from the full record count.
    n = len(items)
    starts = [p[0] for p in periods]
    total_c = 0

    out_periods = []
    for pi, (start, end) in enumerate(periods):
        u = starts[pi + 1] if pi + 1 < len(periods) else b + 1
        affected = set()
        for f, recs in records_of.items():
            last_path = None  # this flow's most recent earlier record
            for t, path in recs:
                if start <= t < u:
                    if path == () or (last_path is not None
                                      and path != last_path):
                        affected.add(f)
                last_path = path
                if t >= u:
                    break

        if not affected:
            out_periods.append([start,
                                None if end is None else end,
                                None, None, 0, []])
            continue

        # Adjacent path changes in [start, r] (or [start, U) with no r):
        # consecutive records of the same flow whose paths differ, both
        # ticks inside the window.
        def change_count(limit):
            count = 0
            for f in affected:
                previous = None
                for t, path in records_of[f]:
                    if start <= t < limit:
                        if previous is not None and path != previous[1]:
                            count += 1
                    previous = (t, path)
                    if t >= limit:
                        break
            return count

        r = None
        if end is not None:
            # Earliest tick of [end, U) by which every affected flow has a
            # non-empty path on its latest record at that tick.
            ready = {}
            for f in affected:
                latest = None
                for t, path in records_of[f]:
                    if t >= u:
                        break
                    if path != ():
                        latest = t
                ready[f] = latest
            candidate = max(end, max(ready.values()))
            if candidate < u and all(ready[f] is not None
                                     and ready[f] <= candidate
                                     for f in affected):
                r = candidate

        if r is None:
            c = change_count(u)
            total_c += c
            out_periods.append([start, end, None, None, c,
                                sorted(affected)])
        else:
            c = change_count(r + 1)
            total_c += c
            out_periods.append([start, end, r, r - start, c,
                                sorted(affected)])

    return {"a": a, "b": b, "p": out_periods}


