        affected = set()
        for f, rs in recs.items():
            prev = None
            for t, p in rs:
                if start <= t and (end is not None and t < end
                                   or end is None and t < U):
                    if p == () or (prev is not None and p != prev):
                        affected.add(f)
                prev = p
                if t >= U:
                    break
        if not affected:
            out.append([start, end, None, None, 0, []])
            continue
        # recovery: union of bad intervals
        ivs = []
        for f in affected:
            rs = recs[f]
            for idx, (t, p) in enumerate(rs):
                if start <= t < U and p == ():
                    n = None
                    for t2, p2 in rs[idx + 1:]:
                        if t2 >= U:
                            break
                        if p2 != ():
                            n = t2
                            break
                    ivs.append((t, U if n is None else n))
        ivs.sort()
        merged = []
        for e, n2 in ivs:
            if merged and e < merged[-1][1]:
                if n2 > merged[-1][1]:
                    merged[-1][1] = n2
            else:
                merged.append([e, n2])
        r = None
        if end is not None:
            cur = end
            for e, n2 in merged:
                if e <= cur < n2:
                    cur = n2
                elif e > cur:
                    break
            if cur < U:
                r = cur
        if r is None:
            c = 0
            for f in affected:
                prev = None
                for t, p in recs[f]:
                    if start <= t < U and prev is not None and p != prev:
                        c += 1
                    prev = p
                    if t >= U:
                        break
            out.append([start, end, None, None, c, sorted(affected)])
        else:
            c = 0
            for f in affected:
                prev = None
                for t, p in recs[f]:
                    if start <= t <= r and prev is not None and p != prev:
                        c += 1
                    prev = p
                    if t > r:
                        break
            out.append([start, end, r, r - start, c, sorted(affected)])
    return {"a": a, "b": b, "p": out}


def random_case(rng):
    a, b = 0, rng.randint(5, 30)
    nodes = ["n%d" % i for i in range(rng.randint(2, 5))]
    # simple chain/topology all-up
    links = []
    for i in range(len(nodes) - 1):
        links.append({"from": nodes[i], "to": nodes[i + 1], "cost": 1,
                      "up": True, "latency": 1, "bandwidth": 100})
    # extra random edges
    for i in nodes:
        for k in nodes:
            if i != k and rng.random() < 0.25:
                links.append({"from": i, "to": k, "cost": 1, "up": True,
                              "latency": 1, "bandwidth": 100})
    # events: pick node downs/ups
    events = []
    tt = rng.randint(0, 2)
    target = nodes[rng.randrange(len(nodes))]
    while tt <= b:
        events.append([tt, 0, target, False])
        gap = rng.randint(1, 6)
        events.append([tt + gap, 0, target, True])
        tt += gap + rng.randint(1, 6)
    events = [e for e in events if a <= e[0] <= b]
    flows = ["f%d" % i for i in range(rng.randint(1, 4))]
    paths = [[], [nodes[0], nodes[-1]]]
    for n in nodes[1:]:
        if [nodes[0], n] not in paths:
            paths.append([nodes[0], n])
    paths = [p for p in paths if p == [] or
             all((x, y) in {(l["from"], l["to"]) for l in links}
                 for x, y in zip(p, p[1:]))]
    data = []
    t = 0
    seen = set()
    while t <= b:
        if rng.random() < 0.7:
            f = rng.choice(flows)
            if (f, t) not in seen:
                seen.add((f, t))
                data.append([t, f, rng.choice(paths)])
        t += 1
    data.sort(key=lambda x: x[0])
    return nodes, links, a, b, events, data


def run_module(nodes, links, a, b, events, data):
    net = {"nodes": nodes, "links": links}
    import tempfile, os
    fd, path = tempfile.mkstemp(suffix=".json")
    with os.fdopen(fd, "w") as fh:
        json.dump(net, fh)
    proc = subprocess.run(
        [sys.executable, "relay.py", "convstat", path, str(a), str(b),
         json.dumps(events), json.dumps(data)],
        cwd="/home/c/brix2/b/task022", capture_output=True)
    os.unlink(path)
    if proc.returncode != 0:
        return None, proc.stderr.decode()
    return json.loads(proc.stdout.decode()), None


def main():
    rng = random.Random(1234)
    for trial in range(3000):
        nodes, links, a, b, events, data = random_case(rng)
        ref = reference(a, b, events, data)
        got, err = run_module(nodes, links, a, b, events, data)
        if err is not None:
            print("UNEXPECTED FAIL", err)
