            return
        if got != ref:
            print("MISMATCH trial", trial)
            print("events", events)
            print("data", data)
            print("ref ", json.dumps(ref))
            print("got ", json.dumps(got))
            return
    print("FUZZ OK")


if __name__ == "__main__":
    main()

